C = dict(id='GL-24', title='Selling Personal Protective Equipment', group='Business and Commerce', level=4,
 summary='Sell protective equipment responsibly: match the right item to the hazard, check standards and labels, advise honestly and keep records.',
 outcomes=['Explain how hazards, protection types and standards fit together.', 'Apply a hazard-to-equipment match for common workplaces.', 'Analyse supplier claims and labels for evidence of conformity.', 'Create a buyer guide and a safe-sales checklist.', 'Evaluate your advice for accuracy, honesty and limits.'],
 task='Build a buyer guide and a sales process for five types of protective equipment, with supplier checks and a records system.',
 cond='Product samples or catalogues, standards summaries from public sources, a spreadsheet, a mentor with safety experience and a peer circle. About 8 to 10 weeks part-time.',
 std='Each product matched to a named hazard; each supplier check shows a dated conformity document; no medical or false protection claims; records kept for batch numbers; mentor confirms advice is within your role.',
 who='Shop and trade-counter staff, distributors, safety assistants, small traders.', req='None.',
 safety='Wrong equipment can injure. Sell only items with valid conformity evidence for your place, never overstate protection, and send complex risk questions to a qualified safety adviser.',
 mods=[
 ('Hazards and protection', 'Equipment is the last line, after removing or reducing the hazard.', ['Order of control: remove, substitute, guard, train, then protect.', 'Hazards: impact, cut, noise, dust, chemical, heat, falls.', 'Body areas: head, eyes, ears, lungs, hands, feet, body.', 'No item protects against everything.'], 'A worker cutting tiles: dust and flying chips; protect eyes and lungs, ears if loud.', 'Make a hazard-to-body map for three workplaces.', 'Each hazard linked to a body area.'),
 ('Standards and markings', 'Markings show tested performance.', ['Look for the marking, class and the standard number for your place.', 'Markings on products and boxes; read the notice of use.', 'Expiry dates and life limits.', 'Do not accept a mark you cannot trace.'], 'Gloves marked for cut level C protect better than level A; the number and picture show which risk.', 'Decode markings on five samples.', 'Each marking explained.'),
 ('Check suppliers', 'Trust documents, not promises.', ['Ask for conformity declarations and test reports.', 'Check they match the product and batch.', 'Verify with the issuing body where possible.', 'Keep copies and dates.'], 'A supplier\'s certificate names a different model: reject until fixed.', 'Review three supplier documents.', 'Each review ends with accept, query or reject.'),
 ('Fit and use', 'Wrong fit means no protection.', ['Sizes and adjustments.', 'Compatibility: glasses with masks, ear and head gear.', 'Training: put on, check, take off, clean.', 'Replace when damaged.'], 'A mask with a beard gap leaks; advise a different type or a clean shave where allowed.', 'Write a fitting guide for two items.', 'Guide has check steps.'),
 ('Advise honestly', 'Say what an item does and does not do.', ['Ask about the task, place, duration.', 'Offer two options with cost.', 'Never promise full safety.', 'Send tricky cases to an adviser.'], 'Customer asks for one mask for paint, dust and welding; explain they are different hazards.', 'Role-play three customer questions.', 'Advice accurate and polite.'),
 ('Price, stock and records', 'Records protect you and the buyer.', ['Batch numbers on invoices.', 'Stock rotation for dated items.', 'Recalls: contact all buyers fast.', 'Fair prices; no panic selling.'], 'A batch recall: 40 buyers contacted in 24 hours from the sales log.', 'Set up a batch log and test a recall.', 'Recall test under 24 hours.'),
 ('Ethics and rules', 'Avoid false or illegal claims.', ['No health cures or guaranteed protection.', 'Import and sale rules for your place.', 'Warranty and returns for used items.', 'Report unsafe products.'], 'An advert claims "100% safe": rewrite as "tested to the stated standard".', 'Review five adverts for claims.', 'Each claim fixed or removed.'),
 ('Guide and review', 'Package your knowledge.', ['One-page buyer guide.', 'Safe-sales checklist.', 'Peer review.', 'Plan 90 days.'], 'Guide cut from three pages to one using pictures.', 'Publish and test the guide.', 'Three users find the right item.')],
 quiz=[('What is the order of control?', 'Remove, substitute, guard, train, then protect.'), ('Why check conformity documents?', 'To confirm the product was tested.'), ('Can one item protect against everything?', 'No.'), ('Why record batch numbers?', 'To contact buyers in a recall.'), ('Why not say "100% safe"?', 'It is false and can be unlawful.'), ('What if a customer has a complex risk?', 'Send them to a qualified safety adviser.'), ('Why check fit?', 'A poor fit lets hazards through.'), ('Where find limits on use?', 'The notice of use.'), ('What to do with a mismatched certificate?', 'Reject until corrected.'), ('Why question the task?', 'The right item depends on the hazard.')],
 rubric=[('Hazard match', 'Maps complete', 'Cases checked by an adviser'), ('Supplier checks', 'Three reviewed', 'Rejects handled'), ('Advice quality', 'Accurate and honest', 'Customer feedback strong'), ('Records', 'Batch log working', 'Recall under 24 hours'), ('Compliance', 'No false claims', 'Adverts audited')],
 jobs=[('PPE sales associate', 'Advises and sells equipment'), ('Safety supplies buyer', 'Checks suppliers'), ('Trade counter assistant', 'Serves tradespeople'), ('Distributor assistant', 'Keeps records and batches')],
 next='Marketplace Fulfilment Selling; E-Commerce Inventory Management; Inclusive and Minority-Owned Business Growth.',
 local='Standards, markings and import rules for protective equipment differ greatly by place: use the local regulator\'s list.',
 evidence='Your evidence: hazard maps, marking decodes, supplier reviews, fitting guide, batch log, advert review and buyer guide.',
 ladder=[('Basics of safety', 'Name the main hazards at work (cuts, dust, noise, chemicals) and the kind of protection for each. Notes: tour a workplace or a home workshop and photograph the hazards. Standard: each hazard has a protection type.'), ('Awareness', 'Describe the main protection types and why a wrong match is dangerous. Notes: handle samples under supervision and read the labels. Standard: you can say what each label means.'), ('Foundation', "Match a user's job to the right equipment and explain what the buyer must check (rating, fit, expiry). Notes: use five case cards. Standard: four of five matched with reasons."), ('Practitioner', 'Run a sale conversation with a practice buyer, check needs, explain limits and refuse an unsafe request. Notes: record the refusals. Standard: no sale made against the rating or the law.'), ('Specialist', 'Build a buyer guide and a sales process for five types of protective equipment, with supplier checks and a records system. Notes: records cover batch, expiry, certificate and recall steps. Standard: each product traces to a certificate and each recall step is tested.'), ('Advanced', 'Run a supply operation with audits, recall drills and staff training. Notes: add a certificate check at each delivery. Standard: audit findings closed and recall drill within the target time.'), ('Super expert', 'Set the hazard-to-protection matching method for selling protective equipment and teach the sellers who use it. Notes: re-read the standards and labelling rules for the place each year and refresh the sales scripts.')])

C['deep'] = dict(mods=[
 ('Treating protective equipment as the first fix.', 'A noisy workshop buys earplugs but never reduces the noise at source; advise a quieter machine and guards first.', 'What hazard could be removed before any item is sold?'),
 ('Trusting a mark because it looks official.', 'A mask has a mark with no standard number; ask for the declaration before listing.', 'Which marking on your sample can you not trace?'),
 ('Accepting a certificate for a different model.', 'Certificate for model X-1 is attached to listing X-2; reject until corrected.', 'Which supplier document did you query?'),
 ('Ignoring facial hair or head size when fitting.', 'A half mask leaks on a bearded worker; advise a loose-fitting hood type.', 'What fit check did you teach?'),
 ('Saying "this will keep you safe".', 'Say "tested to the stated standard for dust; it does not protect against vapours".', 'What does your item not protect against?'),
 ('Selling expired stock.', 'Filters expire after five years sealed; check dates at goods-in.', 'How do you rotate dated items?'),
 ('Copying a competitor\'s claim.', 'Copied claim "medical grade" is unproven; delete it.', 'Which advert claim did you change?'),
 ('Writing a guide that hides limits.', 'Guide has a clear "Not for" line for each item.', 'Does each guide entry state a limit?')],
 gloss=[('Hazard', 'Something that can cause harm.'), ('Risk', 'Chance of harm times how bad it is.'), ('Conformity declaration', 'The maker\'s statement that a product meets a standard.'), ('Batch', 'Items made together and traceable.'), ('Notice of use', 'Instructions and limits supplied with the item.'), ('Recall', 'Calling back unsafe products.')],
 cases=[('The wrong mask', 'A customer buys a dust mask for spray painting.', 'What do you do?', 'Explain the hazard is vapour, suggest the correct respirator type and send complex cases to a safety adviser.'),
        ('The recall', 'A maker recalls a batch of gloves.', 'What steps?', 'Use the batch log to contact buyers within 24 hours, remove stock and keep records.')])
C['deep']['extra'] = [
 ['Walk through a workplace with a checklist and list hazards by area.', 'Ask workers what hurts or irritates.'],
 ['Compare two similar items and explain the difference in marking.', 'Note that some marks cover one hazard only.'],
 ['Record the date you saw each document.', 'Ask suppliers for test report numbers.'],
 ['Teach put-on and take-off order.', 'Show how to clean and store each item.'],
 ['Keep a list of questions to ask every customer.', 'Offer a low-cost and a better option.'],
 ['Label shelves with batch numbers.', 'Separate damaged returns.'],
 ['Track which adverts you changed.', 'Check platform rules for health claims.'],
 ['Add pictures to the buyer guide.', 'Review the guide when standards change.']]

_ex = ['A worker cutting tiles faces dust and flying chips. The control order: use wet cutting to cut dust, then eye protection and a suitable mask, ear protection if the saw is loud.', 'Gloves marked for cut level C protect better than level A; the number and the picture tell you which risk. You decode five samples and record each marking.', "A supplier's certificate names model X-1 but the listing is X-2. You reject the listing and ask for the right document, with the date of the check noted.", 'A half mask leaks on a bearded worker. You advise a loose-fitting hood type, show the fit check and note the limit in the guide.', 'A customer asks for one mask for paint, dust and welding. You explain they are different hazards and offer three correct options with prices.', 'A batch recall: 40 buyers are contacted in 24 hours from the sales log and the stock is removed.', "An advert says '100% safe'. You rewrite it as 'tested to the stated standard for dust; not for vapours'.", "The one-page guide has a 'Not for' line for each item; three test users pick the right item in under a minute."]
_extra = ['Walk a workplace with a checklist and write the hazards by area.', 'Ask workers which tasks cause the most discomfort.', 'Compare two similar items and explain the difference in markings.', 'Ask suppliers for test report numbers and keep a copy.', 'Record the date you checked every document.', 'Teach the put-on, check and take-off order for each item.', 'Show how to clean and store equipment.', 'Offer a low-cost and a better option with clear reasons.', 'Label shelves with batch numbers and dates.', 'Separate damaged returns from good stock.', 'Check platform rules for health claims in adverts.', 'Keep a list of claims you removed.', 'Add pictures to the buyer guide.', 'Review the guide when standards change.', 'Send complex cases to a qualified safety adviser.', 'Write three lessons and a 90-day plan.']
C['deep']['mods'] = [(m[0], _ex[i], m[2]) for i, m in enumerate(C['deep']['mods'])]
C['deep']['extra'] = [_extra[2*i:2*i+2] for i in range(8)]
_np = [['Start every sale by naming the hazard, such as dust, noise above 85 dB, splashes or falling objects, before you name a product, so the customer buys for the risk.', 'Before recommending anything, ask three questions: what task the buyer does, for how many hours each day, and what the work area is like, then write the answers on the sale note.'], ['Look for the standard number and rating printed on the item itself, not only on the box, and keep a photo of each marking in your product file.', 'Compare the marking with the hazard: a mask rated for light dust is unsuitable for fine hazardous powder, so always match the rating class to the task.'], ['Ask each supplier for a current test certificate and check its issue date; if the certificate is older than the latest product design change, request an updated one.', 'Keep a supplier file with certificate, contact, delivery record and any returns, and review it each year to drop unreliable sources.'], ['Let the customer try the item on and move around for two minutes, checking for gaps, pressure points and fogging before the sale is completed.', 'Show the customer how to put on, adjust, check and store the item, and hand over a one-page card so they repeat the steps correctly at work.'], ['Say plainly what an item does not protect against, for example that a basic dust mask does not stop fumes, and point the buyer to the right product or an expert.', 'Never promise total safety; use wording such as "designed to reduce", and refer complex or high-risk jobs to a qualified safety adviser.'], ["Record each batch number against the sales it covers so you can contact buyers quickly if a fault is found, and keep the record for the item's expected life.", 'Compare prices by cost per use, for example gloves lasting two weeks against a cheaper pair lasting two days, and show the buyer this comparison honestly.'], ['Never sell counterfeit or expired items, and remove any item with damaged packaging or a missing marking from the shelf on the day you notice it.', 'Check the product-labelling and selling rules that apply where you trade, keep receipts and warranty terms, and tell each customer how to report a fault or return a product.'], ['Run a short checklist at the end of each sale: hazard named, item matched, fit checked, advice given and record saved, then count the fully completed sales every week.', 'Review complaints and returns every month, find the most common cause, and then update your advice card or change your supplier choice to remove it.']]
C['mods'] = [(m[0], m[1], list(m[2])+_np[i], m[3], m[4], m[5]) for i, m in enumerate(C['mods'])]

_dupfix = {"2": "A hard hat shows an impact class and a date code; you read the date, see it is 6 years old, and tell the buyer to check the maker's life limit before use.", "5": "A customer wants cheap ear plugs for a loud sawmill; you explain that the noise level matters, ask for the reading, and offer ear muffs rated for it at 28 instead of plugs at 3.", "6": "A pack of 200 gloves is sold ten at a time; the log lets you find the 3 buyers of a lot with a stitching fault the same afternoon.", "7": "A leaflet says 'stops all accidents'; you replace it with 'helps protect against the hazards named on the label when worn correctly'."}
C['deep']['mods'] = [(m[0], _dupfix.get(str(i + 1), m[1]), m[2]) for i, m in enumerate(C['deep']['mods'])]
C['intro_add'] = ['You will be able to name the main workplace hazards and explain why protective gear is the final defence after removing or reducing the risk itself.', 'You will be able to read standard numbers and ratings on labels and match a marking to the task it was tested for.', 'You will be able to vet suppliers by checking certificates and delivery history, so the goods you stock rest on evidence, not claims.', 'You will be able to fit an item to a person and demonstrate its use, because a poorly fitted mask or glove gives little protection.', "You will be able to describe each product's limits in plain words, so no buyer assumes cover the item cannot provide.", 'You will be able to link batch numbers to sales and price by cost per use, enabling quick recalls and fair comparisons.', "You will be able to spot false claims, counterfeit stock and rule breaches, protecting your customers and your shop's name.", 'You will be able to turn your product knowledge into a one-page advice card and improve it using complaint and return patterns.']
